/// The grammar: paradigms, the rules choosing one, irregular forms.
pub static GRAMMAR: Grammar<'static, Declension, u8, crate::Gender> = Grammar {
    orthography: crate::orthography::ORTHOGRAPHY,
    cells: 24,
    lemma_cell: None,
    capitalized: false,
    paradigms: Cow::Borrowed(&paradigms::DECLENSIONS),
    paradigm: rules::DECLENSION,
    referrals: Cow::Borrowed(&gender::REFERRALS),
    feature: Some(gender::GENDER),
    compound: None,
    prefixes: None,
    accent: None,
    laws: None,
    spellings: Cow::Borrowed(spellings::SPELLINGS),
    marks: None,
    irregular: irregular::IRREGULAR,
    smoothing: 2.0,
    sharpness: 1.0,
};

/// A noun form: which cell of its declension.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// A noun in a case and number.
    Form(crate::Case, crate::Number),
}

impl Cell {
    /// Its place in a paradigm.
    pub const fn index(self) -> usize {
        let cell = match self {
            Cell::Form(crate::Case::Nominative, crate::Number::Singular) => cell::NOM_SG,
            Cell::Form(crate::Case::Nominative, crate::Number::Dual) => cell::NOM_DU,
            Cell::Form(crate::Case::Nominative, crate::Number::Plural) => cell::NOM_PL,
            Cell::Form(crate::Case::Accusative, crate::Number::Singular) => cell::ACC_SG,
            Cell::Form(crate::Case::Accusative, crate::Number::Dual) => cell::ACC_DU,
            Cell::Form(crate::Case::Accusative, crate::Number::Plural) => cell::ACC_PL,
            Cell::Form(crate::Case::Instrumental, crate::Number::Singular) => cell::INS_SG,
            Cell::Form(crate::Case::Instrumental, crate::Number::Dual) => cell::INS_DU,
            Cell::Form(crate::Case::Instrumental, crate::Number::Plural) => cell::INS_PL,
            Cell::Form(crate::Case::Dative, crate::Number::Singular) => cell::DAT_SG,
            Cell::Form(crate::Case::Dative, crate::Number::Dual) => cell::DAT_DU,
            Cell::Form(crate::Case::Dative, crate::Number::Plural) => cell::DAT_PL,
            Cell::Form(crate::Case::Ablative, crate::Number::Singular) => cell::ABL_SG,
            Cell::Form(crate::Case::Ablative, crate::Number::Dual) => cell::ABL_DU,
            Cell::Form(crate::Case::Ablative, crate::Number::Plural) => cell::ABL_PL,
            Cell::Form(crate::Case::Genitive, crate::Number::Singular) => cell::GEN_SG,
            Cell::Form(crate::Case::Genitive, crate::Number::Dual) => cell::GEN_DU,
            Cell::Form(crate::Case::Genitive, crate::Number::Plural) => cell::GEN_PL,
            Cell::Form(crate::Case::Locative, crate::Number::Singular) => cell::LOC_SG,
            Cell::Form(crate::Case::Locative, crate::Number::Dual) => cell::LOC_DU,
            Cell::Form(crate::Case::Locative, crate::Number::Plural) => cell::LOC_PL,
            Cell::Form(crate::Case::Vocative, crate::Number::Singular) => cell::VOC_SG,
            Cell::Form(crate::Case::Vocative, crate::Number::Dual) => cell::VOC_DU,
            Cell::Form(crate::Case::Vocative, crate::Number::Plural) => cell::VOC_PL,
        };
        cell as usize
    }
}

impl From<(crate::Case, crate::Number)> for Cell {
    fn from((case, number): (crate::Case, crate::Number)) -> Self {
        Cell::Form(case, number)
    }
}

/// A noun to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Noun<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
    gender: Option<crate::Gender>,
}

impl<'w> Noun<'w> {
    /// The noun `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Noun {
            lemma,
            given: Vec::new(),
            gender: None,
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    /// Its gender, which says which cell its `referred` forms (see its
    /// declension) are taken from.
    #[must_use]
    pub fn gender(mut self, gender: Gender) -> Self {
        self.gender = Some(gender);
        self
    }

    fn known(&self) -> Known<'_, crate::Gender> {
        Known {
            forms: &self.given,
            feature: self.gender,
            full: false,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The declensions it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn declension(&self) -> Vec<Reading<'static, 'static, Declension>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
